export const researchOverlayVersion = "2026-04-26-pass-5";

const baseCommonNotes = [
  "Sörmlandsleden does not guarantee water quality or availability; treat or filter natural sources and carry backup.",
  "Shelters are generally free, shared, first-come, cannot be booked, and do not guarantee firewood or trash service."
];

const reserveCommonNotes = [
  "In nature reserves, local camping and fire rules override allemansrätten; fires are often restricted to prepared fireplaces."
];

function sourceUrl(stage) {
  const officialStageSlugOverrides = new Map([
    ["5:1", "51"],
    ["5:3", "53"],
    ["15:2", "152"],
    ["23:1", "231"],
    ["24:1", "241"],
    ["27:1", "271"]
  ]);
  const stageKey = String(stage);
  const slug = officialStageSlugOverrides.get(stageKey) ?? stageKey.replace(":", "-");
  return `https://www.sormlandsleden.se/vandring/etapp/etapp-${slug}/`;
}

function facility(stage, id, name, type, coordinates, description, provider = "sormlandsleden", url = sourceUrl(stage)) {
  return {
    id: `sormlandsleden-stage-${String(stage).replace(":", "-")}-${id}`,
    name,
    type,
    sectionId: `sormlandsleden-stage-${String(stage).replace(":", "-")}`,
    coordinates,
    description,
    source: {
      provider,
      url,
      lastFetchedAt: "2026-04-26"
    }
  };
}

function stageOverlay(stage, { utilities = [], waterSources = [], notes = [], facilities = [], includeReserveCommonNote = true }) {
  return {
    utilities,
    waterSources,
    notes: [...baseCommonNotes, ...(includeReserveCommonNote ? reserveCommonNotes : []), ...notes],
    facilities: facilities.map((item) => facility(stage, ...item))
  };
}

