export function applySormlandsledenResearchOverlays(section) {
  const overlay = sormlandsledenResearchOverlays[String(section.stageNumber)];
  if (!overlay) return section;

  const existingFacilityIds = new Set((section.facilities ?? []).map((facility) => facility.id));
  const overlayFacilities = overlay.facilities.filter((facility) => !existingFacilityIds.has(facility.id));
  const placeholderPattern =
    /(still needs the full enrichment pass|official section imported|conservative official-summary markers|exact sub-location still needs|no verified water refill has been deeply researched|until enriched)/i;
  const removePlaceholders = (items = []) => items.filter((item) => !placeholderPattern.test(item));

  return {
    ...section,
    utilities: [...new Set([...removePlaceholders(section.utilities), ...overlay.utilities])],
    waterSources: overlay.waterSources.length ? overlay.waterSources : section.waterSources,
    notes: [...new Set([...removePlaceholders(section.notes), ...overlay.notes])],
    facilities: [...(section.facilities ?? []).filter((facility) => !/Official Sörmlandsleden lists/i.test(facility.description)), ...overlayFacilities]
  };
}
